     */
    public ClaimStatus statusOn(LocalDate end) {
        if (log == null || log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogLine line : log) {
            if (!LocalDate.parse(line.on()).isAfter(end)) {
                then = line.status();
            }
        }
        return then;
    }

