package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;

/**
 * The sheet as it stood at the end of each of its todays: when the sheet's today moves on, what it holds is kept,
 * so a date's state is the one kept when the today first moved from on or before that date to after it.
 */
@Repository
public class SheetStates {

    private final JdbcTemplate jdbc;
    private final JsonMapper json;
    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final Settings settings;

    public SheetStates(JdbcTemplate jdbc, JsonMapper json, People people, Claims claims, Rates rates,
            Settings settings) {
        this.jdbc = jdbc;
        this.json = json;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.settings = settings;
    }

    /** What the sheet holds now. */
    public SheetState now(String sheet) {
        return new SheetState(people.list(sheet), claims.list(sheet), rates.list(sheet),
                settings.history(sheet, Settings.FLOOR), settings.history(sheet, Settings.LATE_PCT),
                settings.history(sheet, Settings.CAP), settings.get(sheet, Settings.POLICY_DATE));
    }

    /** Keeps what the sheet holds now, as its today moves from one date to another. */
    public void keep(String sheet, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO sheet_state (sheet, from_today, to_today, state) VALUES (?, ?, ?, ?)", sheet,
                Date.valueOf(from), Date.valueOf(to), json.writeValueAsString(now(sheet)));
    }

    /**
     * What the sheet held at the end of the date, before its today: the state kept when the today first moved from on
     * or before it to after it; null when the today was never on or before it.
     */
    public SheetState at(String sheet, LocalDate date) {
        List<String> found = jdbc.queryForList("SELECT state FROM sheet_state WHERE sheet = ? AND from_today <= ?"
                + " AND to_today > ? ORDER BY id LIMIT 1", String.class, sheet, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : json.readValue(found.get(0), SheetState.class);
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { hundredths } from '../rates/rates';

/** The sheet's settings: the clerk limit with two decimals, the most due a clerk may settle ('' for no limit);
 *  the floor with two decimals, the least a claim's live due is; and the terms, the whole days after its date by
 *  which a claim is due; and the late percent with two decimals, charged on an overdue claim's figure for every
 *  full 30 days it is overdue; and the policy date (yyyy-MM-dd; '' for the sheet's today): a claim dated before it
 *  rounds half up, on or after it half to even; and the period numbering from-date (yyyy-MM-dd; '' for off): while
 *  the sheet's today is on or after it, a claim opened is numbered within its period; and each grade's own terms
 *  (whole days; '' when it takes the sheet's terms), from which a claim's due-by is fixed when it is added; and the
 *  cap with two decimals, the most a person's due-total is ('' for no cap). Each is the value in force on the sheet's
 *  today. And each action's permitted roles in the permission matrix (comma separated; '' for its standing rule). And the
 *  grace days (whole days; '' for off): a today change closes each open period whose to-date plus them is before it.
 *  And the entry date (yyyy-MM-dd; '' for off): while set, a new claim's date defaults to it instead of the sheet's today.
 *  And, for each dated key (every one that carries a figure), its values as recorded, by from-date. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string;
  proofThreshold: string; noteThreshold: string; graceDays: string; entryDate: string; perms: Partial<Record<PermAction, string>>; dated: Partial<Record<SettingKey, DatedValue[]>> };

/** A dated setting's value as recorded: in force from its from-date (yyyy-MM-dd). */
export type DatedValue = { from: string; value: string };

/** A figure in force by date (yyyy-MM-dd), in hundredths. */
export type DatedCents = (date: string) => bigint;

/** Whether a setting is dated: every one that carries a figure is; the policy, period numbering and entry dates and the grace days are not. */
export function isDated(key: SettingKey): boolean {
  return key !== 'policy-date' && key !== 'period-numbering-from' && key !== 'grace-days' && key !== 'entry-date' && !key.startsWith('perm-');
}

/** The figure in force on a date: the value of the latest from-date on or before it, before every from-date (or
 *  where a blank is in force) the starting value. */
function datedCents(values: DatedValue[] | undefined, start: string): DatedCents {
  const sorted = [...(values ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  return (date) => {
    let value = start;
    for (const v of sorted) {
      if (v.from > date) break;
      value = v.value === '' ? start : v.value;
    }
    return hundredths(value);
  };
}

/** A setting's key as the server names it, with the field of {@link Settings} that shows it. */
export type SettingKey = 'clerk-limit' | 'floor' | 'terms' | 'late-pct' | 'policy-date' | 'period-numbering-from'
  | 'terms-A' | 'terms-B' | 'terms-C' | 'cap' | 'proof-threshold' | 'note-threshold' | 'grace-days' | 'entry-date' | `perm-${PermAction}`;

/** The actions whose roles the permission matrix sets, each with its standing rule (used while its entry is blank). */
export const PERMISSIONS = [
  { action: 'open', standing: 'clerk,steward' },
  { action: 'settle', standing: 'clerk,steward' },
  { action: 'void', standing: 'clerk,steward' },
  { action: 'reassign', standing: 'steward' },
  { action: 'close', standing: 'clerk,steward' },
  { action: 'reopen', standing: 'steward' },
] as const;

export type PermAction = (typeof PERMISSIONS)[number]['action'];

/** The grades that may have terms of their own, with the setting key and field of {@link Settings} of each. */
export const GRADE_TERMS = [
  { grade: 'A', key: 'terms-A', field: 'termsA' },
  { grade: 'B', key: 'terms-B', field: 'termsB' },
  { grade: 'C', key: 'terms-C', field: 'termsC' },
] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The terms a sheet starts with. */
export const DEFAULT_TERMS = '14';

export const settingsKey = (sheet: string) => ['settings', sheet] as const;

export const settingsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/settings`;

export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(settingsPath(sheet)),
  });
}

/** The sheet's floor in hundredths by date: the least a claim's live due is, the one in force on its date. */
export function useFloorCents(sheet: string): DatedCents {
  const { data } = useSettings(sheet);
  return datedCents(data?.dated?.floor, DEFAULT_FLOOR);
}

/** The sheet's cap in hundredths: the most a person's due-total is; undefined when there is none. */
export function useCapCents(sheet: string): bigint | undefined {
  const { data } = useSettings(sheet);
  return data?.cap ? hundredths(data.cap) : undefined;
}

/** The sheet's late percent in hundredths by date: charged on an overdue claim's figure for every full 30 days it is
 *  overdue, the one in force on each 30-day boundary after its due-by. */
export function useLatePctCents(sheet: string): DatedCents {
  const { data } = useSettings(sheet);
  return datedCents(data?.dated?.['late-pct'], DEFAULT_LATE_PCT);
}

/** The sheet's policy date (yyyy-MM-dd), or '' when it is the sheet's today. */
export function usePolicyDate(sheet: string): string {
  const { data } = useSettings(sheet);
  return data?.policyDate ?? '';
}

/** Whether a claim is a correction: a negative amount, correcting the settled claim it names by number. */
export function correction(claim: Claim): boolean {
  return claim.amount.startsWith('-');
}

/** Whether a claim keeps its figure whatever the rates: fixed when settled, or bound by a statement (a claim
 *  settled or bound when its grade had no rate keeps none). */
export function fixed(claim: Claim): boolean {
  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
}

/** What makes an overdue claim's late charge: the sheet's late percent (in hundredths) by date, the one in force on
 *  each 30-day boundary after the claim's due-by, and its today.
 *  The charge is never bound by a statement: it follows the sheet's today. It also carries the sheet's policy date
 *  (yyyy-MM-dd; undefined: its today), which decides how a claim's live figures round. */
export type Late = { pct: DatedCents; today: string | undefined; policy: string | undefined };

/** The sheet's late percent, today and policy date. */
export function useLate(sheet: string): Late {
  const today = useSheetToday(sheet);
  const policy = usePolicyDate(sheet);
  return { pct: useLatePctCents(sheet), today, policy: policy === '' ? today : policy };
}

/** Whether a claim's live figures round half up: it rounds on a date (its own, or for a correction the date of the
 *  claim it corrects) before the policy date; on or after it they round half to even. */
export function roundsHalfUp(claim: Claim, late: Late): boolean {
  return late.policy !== undefined && claim.roundsOn < late.policy;
}

/** A claim's figure: the one fixed when it was settled, else the rate figure its statement bound, else its amount at the
 *  grade's rate in force on its date (in hundredths); the floor is applied last, in {@link claimDueCents}. */
export function claimFigureCents(claim: Claim, pct: string | undefined, floor: DatedCents, halfUp = false): bigint | undefined {
  if (claim.settledDue !== null) return hundredths(claim.settledDue);
  if (bound(claim)) return claim.statedDue === null ? undefined : hundredths(claim.statedDue);
  return dueCents(claim.amount, pct, halfUp);
}

/** The whole days a claim is overdue: from its due-by to the sheet's today (0 when it is not overdue). */
function daysOverdue(claim: Claim, late: Late): number {
  if (!overdue(claim, late.today)) return 0;
  return Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000);
}

/** The day (yyyy-MM-dd) the given number of days after a day. */
function plusDays(day: string, days: number): string {
  return new Date(Date.parse(`${day}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
}

/** A claim's late charge on its figure (in hundredths): for each full 30 days it is overdue, the late percent in
 *  force on that boundary (its due-by plus 30, 60, 90 ... days) of the figure, rounded as the claim's live figures
 *  are (see {@link roundsHalfUp}), the charges added up; a correction has none. */
export function lateCents(claim: Claim, figure: bigint, late: Late): bigint {
  if (correction(claim)) return 0n;
  const periods = Math.floor(daysOverdue(claim, late) / 30);
  let total = 0n;
  for (let k = 1; k <= periods; k++) {
    const pct = late.pct(plusDays(claim.dueBy, 30 * k));
    if (pct === 0n) continue;
    const product = figure * pct;
    const quotient = product / 10000n;
    const remainder = product % 10000n;
    const up = remainder > 5000n || (remainder === 5000n && (roundsHalfUp(claim, late) || quotient % 2n === 1n));
    total += up ? quotient + 1n : quotient;
  }
  return total;
}

/** A claim's due: the one fixed when settled; else the greater of the sheet's floor in force on its date and its
 *  figure plus, while it is overdue, its late charge on that figure (a correction has no floor and no charge). */
export function claimDueCents(claim: Claim, pct: string | undefined, floor: DatedCents, late: Late): bigint | undefined {
  const figure = claimFigureCents(claim, pct, floor, roundsHalfUp(claim, late));
  if (figure === undefined || claim.settledDue !== null || correction(claim)) return figure;
  const charged = figure + lateCents(claim, figure, late);
  const least = floor(claim.date);
  return charged >= least ? charged : least;
}


/** A person's due-total: the sum of their counted claims' rounded figures (the claims of others are skipped). n/a (undefined) when their grade
 *  has no rate on the sheet's today, unless a claim has a figure apart from it (settled, stated, at another grade
 *  in force on its date, or from a rate that ended by today on a claim not dated after it): then the figures there are.
 *  With a cap, a due-total above it is the cap (an n/a one is not capped). */
export function personDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
  floor: DatedCents,
  late: Late,
  cap?: bigint,
): bigint | undefined {
  const sum = uncappedPersonDueCents(claims, rates, person, today, floor, late);
  return sum !== undefined && cap !== undefined && sum > cap ? cap : sum;
}

/** A person's due-total before the cap: the sum of their figures (see {@link personDueCents}). */
export function uncappedPersonDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  today: string | undefined,
  floor: DatedCents,
  late: Late,
): bigint | undefined {
  const mine = counted(claims.filter((c) => c.person === person.id), [person]);
  // A claim has a figure apart from today's grade when it keeps one, or when another grade in force on its date gives one.
  const apart = (c: Claim) => {
    const then = gradeOn(person, c.date);
    return fixed(c) || (then !== undefined && then !== person.grade && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined)
      || (then !== undefined && today !== undefined && c.date <= today && claimFigureCents(c, rateOf(rates, then, c.date), floor) !== undefined);
  };
  if (rateOf(rates, person.grade, today) === undefined && !mine.some(apart)) return undefined;
  return mine.reduce((sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n), 0n);
}

/** A person's settled-total and open-total (in hundredths): the dues of their SETTLED claims that count (at their
 *  frozen figures, corrections included) and of their OPEN and PENDING ones that count (see {@link counted}). Together
 *  they make the due-total before the cap; a claim with no due adds nothing. */
export function splitDueCents(
  claims: Claim[],
  rates: Rate[],
  person: Person,
  floor: DatedCents,
  late: Late,
): { settled: bigint; open: bigint } {
  const split = { settled: 0n, open: 0n };
  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
    if (c.status === 'SETTLED') split.settled += due;
    else if (isOpen(c)) split.open += due;
  }
  return split;
}

/** A person's recent settled figure: the sum of their SETTLED claims' frozen figures dated within the 90 days up to
 *  and including the sheet's today (today and the 89 days before it); a claim settled with no figure adds nothing. */
export function recentSettledCents(claims: Claim[], person: Person, today: string | undefined): bigint {
  if (today === undefined) return 0n;
  const since = plusDays(today, -89);
  return claims
    .filter((c) => c.person === person.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
    .reduce((sum, c) => sum + (c.settledDue === null ? 0n : hundredths(c.settledDue)), 0n);
}

/** Whether a person is active: they have an OPEN or PENDING claim that counts (see {@link counted}) dated within the
 *  30 days up to and including the sheet's today (today and the 29 days before it). */
export function isActive(claims: Claim[], person: Person, today: string | undefined): boolean {
  if (today === undefined) return false;
  const since = plusDays(today, -29);
  return counted(claims.filter((c) => c.person === person.id), [person]).some(
    (c) => isOpen(c) && c.date >= since && c.date <= today,
  );
}

/** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined): boolean {
  return isOpen(claim) && !claim.deferred && today !== undefined && claim.dueBy < today;
}

/** The overdue claims that count (see {@link counted}) among a person's or the sheet's claims, and the sum of
 *  their dues (in hundredths; a claim with no due adds nothing). */
export function overdueCents(
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  late: Late,
  floor: DatedCents,
): { count: number; cents: bigint } {
  const byId = new Map(people.map((p) => [p.id, p]));
  const overdueClaims = counted(claims, people).filter((c) => byId.has(c.person) && overdue(c, late.today));
  const cents = overdueClaims.reduce(
    (sum, c) => sum + (claimDueCents(c, rateOf(rates, gradeOn(byId.get(c.person)!, c.date), c.date), floor, late) ?? 0n),
    0n,
  );
  return { count: overdueClaims.length, cents };
}

/** A person's dues by the age of the claim on the sheet's today (the whole days from its date): their OPEN and
